const listVerificationRuns = `-- name: ListVerificationRuns :many
SELECT id, job_id, attempt_id, status, started_at, finished_at FROM verification_runs
WHERE job_id = $1
ORDER BY started_at, id
`

func (q *Queries) ListVerificationRuns(ctx context.Context, jobID uuid.UUID) ([]VerificationRun, error) {
	rows, err := q.db.Query(ctx, listVerificationRuns, jobID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VerificationRun{}
	for rows.Next() {
		var i VerificationRun
		if err := rows.Scan(
			&i.ID,
			&i.JobID,
			&i.AttemptID,
			&i.Status,
			&i.StartedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockAttempt = `-- name: LockAttempt :one
SELECT id, job_id, attempt_number, worker_id, status, exit_code, error, started_at, finished_at FROM job_attempts
WHERE id = $1
FOR UPDATE
`

// LockAttempt serializes reports about one attempt for the rest of the transaction.
func (q *Queries) LockAttempt(ctx context.Context, id uuid.UUID) (JobAttempt, error) {
	row := q.db.QueryRow(ctx, lockAttempt, id)
	var i JobAttempt
	err := row.Scan(
		&i.ID,
		&i.JobID,
		&i.AttemptNumber,
		&i.WorkerID,
		&i.Status,
		&i.ExitCode,
		&i.Error,
		&i.StartedAt,
		&i.FinishedAt,
	)
	return i, err
}

const nextAttemptNumber = `-- name: NextAttemptNumber :one
SELECT (coalesce(max(attempt_number), 0) + 1)::integer AS next
FROM job_attempts
WHERE job_id = $1
`

func (q *Queries) NextAttemptNumber(ctx context.Context, jobID uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextAttemptNumber, jobID)
	var next int32
	err := row.Scan(&next)
	return next, err
}

const recordAttemptExit = `-- name: RecordAttemptExit :exec
UPDATE job_attempts
SET exit_code = $1
WHERE id = $2
`

type RecordAttemptExitParams struct {
	ExitCode *int32
	ID       uuid.UUID
}

func (q *Queries) RecordAttemptExit(ctx context.Context, arg RecordAttemptExitParams) error {
	_, err := q.db.Exec(ctx, recordAttemptExit, arg.ExitCode, arg.ID)
	return err
}

const releaseLeaseByAttempt = `-- name: ReleaseLeaseByAttempt :execrows
UPDATE leases
SET released_at = now()
WHERE attempt_id = $1 AND released_at IS NULL
`

func (q *Queries) ReleaseLeaseByAttempt(ctx context.Context, attemptID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, releaseLeaseByAttempt, attemptID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const renewWorkerLeases = `-- name: RenewWorkerLeases :execrows
UPDATE leases
SET expires_at = now() + make_interval(secs => $1::double precision)
WHERE worker_id = $2
  AND released_at IS NULL
  AND expires_at > now()
`

type RenewWorkerLeasesParams struct {
	TtlSeconds float64
	WorkerID   uuid.UUID
}

// RenewWorkerLeases extends every still-valid lease held by a worker.
func (q *Queries) RenewWorkerLeases(ctx context.Context, arg RenewWorkerLeasesParams) (int64, error) {
	result, err := q.db.Exec(ctx, renewWorkerLeases, arg.TtlSeconds, arg.WorkerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
